15	/// 伙伴分配器的一个行。
16	pub trait BuddyLine {
17	    /// 空集合。用于静态初始化。
18	    const EMPTY: Self;
19	
20	    /// 侵入式元数据的大小。
21	    const INTRUSIVE_META_SIZE: usize = 0;
