52	impl BuddyCollection for LinkedListBuddy {
53	    #[inline]
54	    fn take_any(&mut self, align_order: usize) -> Option<usize> {
55	        if align_order != 0 {
56	            // TODO 需要支持对齐吗？没效率，似乎没必要
57	            None
58	        } else {
59	            self.free_list
60	                .take_any()
61	                .map(|ptr| self.order.ptr_to_idx(ptr))
62	        }
