65	    fn put(&mut self, idx: usize) -> Option<usize> {
66	        // 伙伴和当前结点存在链表的同一个位置。
67	        let node = unsafe { self.order.idx_to_ptr(idx) };
68	        let buddy = unsafe { self.order.idx_to_ptr(idx ^ 1) };
69	        if self.free_list.insert(node, buddy) {
70	            None
71	        } else {
72	            // 插入失败说明伙伴已碰头
73	            Some(idx >> 1)
74	        }
75	    }
